package com.gradeassessment.data.questionbank

import com.gradeassessment.domain.model.Question
import kotlinx.serialization.json.Json

object QuestionBankLoader {

    /** Classpath manifest listing every question file; generated by tools/validate_question_bank.py --normalize. */
    private const val MANIFEST_PATH = "questions/index.json"

    private val json = Json {
        ignoreUnknownKeys = true
        isLenient = true
        coerceInputValues = true
        explicitNulls = false
    }

    /** Problems found while loading (missing files, parse errors, unusable questions). Empty when healthy. */
    @Volatile
    var lastLoadProblems: List<String> = emptyList()
        private set

    /**
     * Loads every question file named in the manifest. O(total questions).
     *
     * [DECISION: manifest file instead of a hard-coded path list. Classpath directories cannot be
     *  listed reliably from inside a packaged jar, and a hard-coded list silently ignored new files.]
     */
    fun loadQuestionsFromResources(): List<Question> {
        val problems = mutableListOf<String>()
        val allQuestions = mutableListOf<Question>()
        val seenIds = HashSet<String>()

        val paths: List<String> = try {
            val manifest = readResource(MANIFEST_PATH)
                ?: error("manifest $MANIFEST_PATH not found on classpath")
            json.decodeFromString<List<String>>(manifest)
        } catch (e: Exception) {
            problems.add("Could not read question manifest: ${e.message}")
            emptyList()
        }

        for (path in paths) {
            try {
                val content = readResource(path)
                if (content == null) {
                    problems.add("Question file listed in manifest is missing: $path")
                    continue
                }
                for (question in json.decodeFromString<List<Question>>(content)) {
                    val defect = question.structuralDefect()
                    when {
                        defect != null -> problems.add("Skipped ${question.id} ($path): $defect")
                        !seenIds.add(question.id) -> problems.add("Skipped duplicate id ${question.id} ($path)")
                        else -> allQuestions.add(question)
                    }
                }
            } catch (e: Exception) {
                problems.add("Could not load $path: ${e.message}")
            }
        }

        problems.forEach { System.err.println("QuestionBankLoader: $it") }
        lastLoadProblems = problems
        return allQuestions
    }

    private fun readResource(path: String): String? =
        this::class.java.classLoader.getResourceAsStream(path)?.use { it.bufferedReader().readText() }
}
